SELECT 'gongkao', '多次相遇周期', 'kp-trv-mm-cycle', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多次相遇周期"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "从第1次相遇到第2次相遇的时间，永远是从出发到第1次相遇时间的 2 倍！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“两人在直线两端不断往返，第 4 次相遇用了多少时间？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这和多次相遇的 (2N-1) 个单程是对应的："}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第1次相遇耗时：t"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第1次到第2次相遇耗时：2t"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第2次到第3次相遇耗时：2t"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出发到第 N 次相遇的总耗时 = t + 2t × (N-1) = (2N-1)t"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记乘时间基数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目说第一次相遇用了 3 小时，问第三次相遇是几小时后。很多同学背了公式 2N-1，直接 2×3-1 = 5，选了5。错！那是 5 个单程。真实时间是 5 × t = 5 × 3 = 15 小时！"}]}]}]}$$ AS jsonb), NULL, '多次相遇周期的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "多次相遇周期"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_mm_cycle", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
